def expand(language):
 words=[];phrases=[];exercises=[];readings=[];lessons=[]
 for i,row in enumerate(VOCAB):
  en,ru,pt,gender,exen,exru,expt=row;word=en if language=='en' else ru;example=exen if language=='en' else exru
  wid=f'{language}-v2-word-{i+1:03}';pid=f'{language}-v2-phrase-{i+1:03}'
  part='conjunção' if i==3 else 'adjetivo' if i==1 else 'substantivo'
  w=dict(id=wid,language=language,word=word,translation=pt,example=example,exampleTranslation=expt,level='B1',topic='Vocabulário intermediário',part=part)
  if language=='ru' and gender:w['gender']=gender
  words.append(w);phrases.append(dict(id=pid,language=language,word=example,translation=expt,example=example,exampleTranslation=expt,level='B1',topic='Expressões contextualizadas',part='frase'))
  exercises.append(dict(id=f'{language}-v2-writing-{i+1:03}',language=language,skill='writing',level='B1',topic=w['topic'],prompt=f'Traduza para {"inglês" if language=="en" else "russo"}: {expt}',answers=[example],wordIds=[wid],explanation=f'{example} — {expt}'))
 for i,(title,topic,text,translation,questions,vocab) in enumerate(READINGS[language]):
  uid=f'{language}-v2-reading-{i+1:03}';ids=[]
  for j,(prompt,answer) in enumerate(questions):
   qid=f'{uid}-q{j+1}';ids.append(qid);variants={'não':['não','nao'],'Maya':['Maya','Maia'],'sim':['sim']}.get(answer,[answer]);exercises.append(dict(id=qid,language=language,skill='reading',level='B1',topic=topic,prompt=prompt,answers=variants,wordIds=[],unitId=uid,explanation=f'Releia o trecho: {translation}'))
  readings.append(dict(id=uid,language=language,level='B1',topic=topic,title=title,text=text,translation=translation,vocabulary=[words[k]['id'] for k in vocab],questionIds=ids))
 for i,(title,objective,explanation,texts,translations,questions,errors) in enumerate(GRAMMAR[language]):
  uid=f'{language}-v2-grammar-{i+1:03}';ids=[]
  for j,(prompt,answer) in enumerate(questions):
   qid=f'{uid}-q{j+1}';ids.append(qid);exercises.append(dict(id=qid,language=language,skill='grammar',level='B1',topic=title,prompt=prompt,answers=[answer],wordIds=[],unitId=uid,explanation=explanation))
  lessons.append(dict(id=uid,language=language,level='B1',topic=title,title=title,objective=objective,explanation=explanation,commonErrors=errors,examples=[dict(text=t,translation=p) for t,p in zip(texts,translations)],questionIds=ids))
  prompt,answer=questions[0];exercises.append(dict(id=f'{language}-v2-test-{i+1:03}',language=language,skill='test',level='B1',topic=title,prompt=prompt,answers=[answer],wordIds=[],explanation=explanation))
 return dict(words=words,phrases=phrases,exercises=exercises,readings=readings,lessons=lessons)

def apply():
 for language in ['en','ru']:
  path=Path(f'frontend/public/learn/{language}.json');data=json.loads(path.read_text(encoding='utf-8'));extra=expand(language)
  for key,rows in extra.items():
   ids={row['id'] for row in data.get(key,[])}
   data.setdefault(key,[]).extend(row for row in rows if row['id'] not in ids)
  
  if language=='ru':
   reading=next(r for r in data['readings'] if r['id']=='ru-v2-reading-001');reading['forms']=[dict(text='опыта',wordId='ru-v2-word-011'),dict(text='Хотя',wordId='ru-v2-word-004')]
  path.write_text(json.dumps(data,ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf-8')

if __name__=='__main__':apply()
